		}

		/**
		 * Check if current user can activate plugins.
		 *
		 * @since 5.0.1
		 * @return bool
		 */
		private function can_activate_plugins() {
			// Core requires `activate_plugins` for all plugin activations.
			if ( ! current_user_can( 'activate_plugins' ) ) {
				return false;
			}

			if ( ! is_multisite() ) { // single site only requires above.
				return true;
			}

			// Network activation also requires access to network plugin management.
			return current_user_can( 'manage_network_plugins' );
		}

		/**
