		private function is_dashboard_plugin_loaded() {
			global $wpmudev_un;

			return class_exists( 'WPMUDEV_Dashboard' ) || ( isset( $wpmudev_un->version ) && version_compare( $wpmudev_un->version, '3.4', '<' ) );
		}

		/**
		 * Init method.
		 *
		 * @return void
		 */
		public function init() {
			if ( $this->is_dashboard_plugin_loaded() ) {
				return;
			}

			if ( is_admin() ) {
				$can_install  = $this->can_install_plugins();
				$can_activate = $this->can_activate_plugins();

				if ( $can_install ) {
					add_filter( 'plugins_api', array( $this, 'filter_plugin_info' ), 101, 3 ); // Run later to work with bad auto update plugins.
					add_action( 'load-plugins.php', array( $this, 'filter_plugin_rows' ), 21 ); // Make sure it runs after WordPress.
				}
				if ( $can_install || $can_activate ) {
					add_action( 'wp_ajax_wdpun-dismiss', array( $this, 'dismiss_ajax' ) );
				}

				// If dashboard is installed but not activated.
				$dash_installed = file_exists( WP_PLUGIN_DIR . '/wpmudev-updates/update-notifications.php' );
				if ( $dash_installed && $can_activate ) {
					add_action( 'admin_print_styles', array( $this, 'notice_styles' ) );
					add_action( 'admin_print_footer_scripts', array( $this, 'notice_scripts' ) );
					add_action( 'all_admin_notices', array( $this, 'activate_notice' ), 5 );
				} elseif ( ! $dash_installed && $can_install ) { // Dashboard not installed at all.
					add_action( 'admin_print_styles', array( $this, 'notice_styles' ) );
					add_action( 'admin_print_footer_scripts', array( $this, 'notice_scripts' ) );
					add_action( 'all_admin_notices', array( $this, 'install_notice' ), 5 );
				}
			}
		}

		/**
		 * Check if we're on an allowed screen.
		 */
		private function is_allowed_screen() {
			if ( is_null( $this->is_allowed_screen ) ) {
				$this->is_allowed_screen = $this->check_allowed_screen();
			}

			return $this->is_allowed_screen;
		}

		/**
		 * Check if we're on an allowed page.
		 *
		 * @return bool
		 */
		private function check_allowed_screen() {
			global $wpmudev_notices;

			$screen = get_current_screen();
			if ( $screen && is_object( $screen ) ) {
				$this->screen_id = $screen->id;
			}

			// Check dismiss flag. Always respect this, regardless of other conditions.
			$dismissed = get_site_option( 'wdp_un_dismissed' );
			if ( $dismissed && $dismissed > strtotime( '-1 week' ) ) {
				return false;
			}

			// Check our registered plugins for hooks.
			if ( isset( $wpmudev_notices ) && is_array( $wpmudev_notices ) ) {
				foreach ( $wpmudev_notices as $product ) {
					if ( isset( $product['screens'] ) && is_array( $product['screens'] ) && in_array( $this->screen_id, $product['screens'], true ) ) {
						$this->product_name = $product['name'];

						return true;
					}
				}
			}

			return false;
		}

