			return wp_nonce_url( $function( 'update.php?action=install-plugin&plugin=install_wpmudev_dash' ), 'install-plugin_install_wpmudev_dash' );
		}

		/**
		 * Activate URL.
		 *
		 * @return string
		 */
		private function activate_url() {
			$function = is_multisite() ? 'network_admin_url' : 'admin_url';
			$url      = 'plugins.php?action=activate&plugin=wpmudev-updates%2Fupdate-notifications.php';

			if ( is_multisite() ) { // requires network activation.
				$url .= '&networkwide=1';
			}

			return wp_nonce_url( $function( $url ), 'activate-plugin_wpmudev-updates/update-notifications.php' );
		}

