		/**
		 * Filter plugin info.
		 *
		 * @param false|object|array $res    The result object or array. Default false.
		 * @param string             $action The type of information being requested from the Installation API.
		 * @param object             $args   API arguments.
		 *
		 * @return false|object|array
		 */
		public function filter_plugin_info( $res, $action, $args ) {
			global $wp_version;
			$cur_wp_version = preg_replace( '/-.*$/', '', $wp_version );

			if ( 'plugin_information' === $action && strpos( $args->slug, 'install_wpmudev_dash' ) !== false ) {
				$res                = new stdClass();
				$res->name          = 'WPMU DEV Dashboard';
				$res->slug          = 'wpmu-dev-dashboard';
				$res->version       = '';
				$res->rating        = 100;
				$res->homepage      = 'https://wpmudev.com/project/wpmu-dev-dashboard/';
				$res->download_link = trailingslashit( $this->server_url ) . 'download-dashboard';
				$res->tested        = $cur_wp_version;

				return $res;
			}

			return $res;
		}

		/**
		 * Filter plugin rows.
		 *
		 * @return void
		 */
		public function filter_plugin_rows() {
			if ( ! current_user_can( 'update_plugins' ) ) {
				return;
			}

			// Don't show on per site plugins list, just like core.
			if ( is_multisite() && ! is_network_admin() ) {
				return;
			}

			$all_plugins = apply_filters( 'all_plugins', get_plugins() );  // only for plugins, nobody cares anymore about themes.

			// don't override existing updates.
			// note: the Pro Plugins that has same "name" possibly get updates from wp.org: https://core.trac.wordpress.org/ticket/23318.
			$updates = get_site_transient( 'update_plugins' );
			$updates = is_object( $updates ) && isset( $updates->response ) ? $updates->response : array();
			foreach ( $all_plugins as $key => $plugin ) {
				if ( ! empty( $plugin['WDP ID'] ) && ! isset( $updates[ $key ] ) ) {
					$hook = 'after_plugin_row_' . $key;
					remove_all_actions( $hook );
					add_action( $hook, array( $this, 'plugin_row' ), 99, 2 );
				}
			}
		}

