											'Your site’s currently disconnected from WPMU DEV. Please <a href="%1$s" target="_blank" title="Activate">activate the Dashboard plugin</a> to stay up to date with %2$s and unlock full features.',
											'wpmudev'
										)
										: /* translators: %1$s: Install Link, %2$s: Plugin Name. */
										__(
											'Your site’s currently disconnected from WPMU DEV. Please <a href="%1$s" target="_blank" title="Install">install the Dashboard plugin</a> to stay up to date with %2$s and unlock full features.',
											'wpmudev'
										),
									array(
										'a' => array(
											'href'   => array(),
											'target' => array(),
											'title'  => array(),
										),
									)
								),
								esc_url( $dash_installed ? $this->activate_url() : $this->auto_install_url() ),
								esc_html( $plugin_data['Name'] ?? $filename )
							);
							?>
						</p>
						<?php
						/**
						 * Append content to an generic notice (Only for WPMU DEV plugins).
						 *
						 * @since 5.0.0
						 *
						 * @param string $filename    Filename.
						 * @param array  $plugin_data Plugin Data.
						 */
						do_action( 'wpmudev_dashboard_notification_after_generic_row_message', $filename, $plugin_data );
						?>
					</div>
					<?php
					/**
					 * Add content after a generic notice (Only for WPMU DEV plugins).
					 *
					 * @since 5.0.0
					 *
					 * @param string $filename    Filename.
					 * @param array  $plugin_data Plugin Data.
					 */
					do_action( 'wpmudev_dashboard_notification_after_generic_row_content', $filename, $plugin_data );
					?>
				</td>
			</tr>
			<?php
		}


		/**
		 * Dismiss ajax callback.
		 *
		 * @return void
		 */
		public function dismiss_ajax() {
			if ( ! check_ajax_referer( 'wdpun-dismiss', 'nonce', false ) ) {
				wp_send_json_error( null, 403 );
			}
			$message_id  = isset( $_POST['msg_id'] ) ? sanitize_key( wp_unslash( $_POST['msg_id'] ) ) : '';
			$can_dismiss = 'activate' === $message_id ? $this->can_activate_plugins() : $this->can_install_plugins();

			if ( ! $can_dismiss ) {
				wp_send_json_error( null, 403 );
			}

			update_site_option( 'wdp_un_dismissed', time() );
			wp_send_json_success();
		}
	}

	$GLOBALS['WPMUDEV_Dashboard_Notice5'] = new WPMUDEV_Dashboard_Notice5();
